float[] hours = new float[6] { 0f, 6f, 12f, 14f, 18f, 21f };
float[] modifiers = new float[6] { 0f, 1f, 1.5f, 2f, 1f, 0f };
int hour = currentHour < 24 ? currentHour : 0;
int from = 0;
int to = 1 % hours.Length;
for (int i = 0; i < hours.Length - 1; i++)
{
    if (hours[i] <= (float)hour && (float)hour < hours[i + 1])
    {
        from = i;
        to = (i + 1) % hours.Length;
        break;
    }
}
float t = ((float)hour - hours[from]) / (hours[to] - hours[from]);
if (t < 0f)
    t = 0f;
else if (t > 1f)
    t = 1f;
return (modifiers[to] - modifiers[from]) * t + modifiers[from];

